// Projection params (equirectangular, latitude-corrected).
const LON0 = -8.14482
const LAT_MAX = 59.34712
const COS = 0.578082
const K = 178.0
export function projectLngLat(lng: number, lat: number): [number, number] {
  return [(lng - LON0) * COS * K, (LAT_MAX - lat) * K]
}

// Inverse of projectLngLat: SVG (x,y) back to [lng, lat]. Because the projection is
// exact, this lets us reuse the hand-tuned SVG scatter as real WGS84 coordinates.
export function unprojectXY(x: number, y: number): [number, number] {
  return [x / (COS * K) + LON0, LAT_MAX - y / K]
}

